s_values = [1, 75, 5625]
N = 75
M = N * N

results = {}

for s in s_values:
    # Calculate G(N) assuming optimal strategy (maximizing new cells)
    # G(N) = 1 + s * floor((M - 1) / s)
    if s == 0:
        G_N = 1
    else:
        K = (M - 1) // s
        G_N = 1 + s * K

    # Calculate minimum C such that G_N <= C * N
    if N > 0:
        C_min = G_N / N
    else:
        C_min = float('inf')

    results[s] = {'G(75)': G_N, 'C_min': C_min}

for s, data in results.items():
    print(f"s={s}: G(75)={data['G(75)']}, C_min={data['C_min']:.4f}")
